namespace mim::bench {
using namespace mim::plug;

void do_bench(int id, std::ofstream* os, const char* prog) {
    auto driver = Driver();
    auto& world = driver.world();
    auto ast    = ast::AST(world);
    auto parser = ast::Parser(ast);
    auto is     = std::istringstream(prog);

    // driver.log().set(&std::cerr).set(Log::Level::Trace);

    ast::Ptrs<ast::Import> imports;
    for (const auto plugin : {"compile", "opt"}) {
        auto mod    = parser.plugin(plugin);
        auto import = ast.ptr<ast::Import>(Loc(), ast::Tok::Tag::K_plugin, Dbg(driver.sym(plugin)), std::move(mod));
        imports.emplace_back(std::move(import));
    }

    auto path = fs::path("myregex.mim");
    if (auto mod = parser.import(is, Loc(&path, Pos(1, 1), Pos(1, 1)))) {
        mod->add_implicit_imports(std::move(imports));
        mod->compile(ast);
        world.call(core::icmp::e, Defs({world.lit_i8(4), world.lit_i8(0)}));
        std::cout << std::format("converting regex to MimIR - set: {}, regex, id: {}", Set, id) << std::endl;
        optimize(world);
        auto f = world.externals().muts().front()->as<Lam>();
        std::cout << "* free vars" << std::endl;

        std::chrono::microseconds::rep fv_ms;
        size_t n;
        {
            auto t1 = std::chrono::steady_clock::now();
            f->free_vars();
            auto t2 = std::chrono::steady_clock::now();
            fv_ms   = std::chrono::duration_cast<std::chrono::microseconds>(t2 - t1).count();
        }

        std::cout << "* nest" << std::endl;
        {
            auto t1   = std::chrono::steady_clock::now();
            auto nest = Nest(f);
            auto t2   = std::chrono::steady_clock::now();
            auto ms   = std::chrono::duration_cast<std::chrono::microseconds>(t2 - t1).count();
            n         = nest.muts().size();

            os[File_FVs] << n << " " << fv_ms << std::endl;
            os[File_Nest] << n << " " << ms << std::endl;
        }

        std::cout << "* beta" << std::endl;
        {
            auto dummy = world.axm(f->type()->dom());
            auto t1    = std::chrono::steady_clock::now();
            auto _     = f->reduce(dummy);
            auto t2    = std::chrono::steady_clock::now();
            auto ms    = std::chrono::duration_cast<std::chrono::microseconds>(t2 - t1).count();
            os[File_Beta] << n << " " << ms << std::endl;
        }

        {
            auto pi   = f->type();
            auto wrap = world.mut_lam(pi)->set("wrap");
            auto ret  = world.mut_con(wrap->var(3, 2)->type()->as<Pi>()->dom());
            wrap->app(false, f, {wrap->var(3, 0), wrap->var(3, 1), ret});
            ret->app(false, wrap->var(3, 2), ret->var());

            f->set<true>("plzinline");
            f->internalize();
            wrap->externalize();

            auto ll   = "regex."s + std::to_string(n) + ".ll"s;
            auto path = fs::path{ll};
            if (fs::exists(path))
                std::cout << "* " << ll << " already exists" << std::endl;
            else {
                std::cout << "* emit " << ll << std::endl;
                auto of = std::ofstream(ll);
                world.driver().backend("ll")(world, of);
            }
        }
    } else {
        throw std::runtime_error("cannot parse program");
    }
}

} // namespace mim::bench

int main(int argc, const char** argv) {
    try {
        std::ofstream ofs[File_Num];
        std::string names[File_Num];
        auto algos = std::array<std::string, File_Num>{"fvs."s, "nest."s, "beta."s};
        auto usage = [argv] { std::cerr << "usage: " << argv[0] << " <suffix>" << std::endl; };

        if (argc != 2) return usage(), EXIT_FAILURE;

        std::string suffix = argv[1];

        for (int i = 0; i != File_Num; ++i) {
            std::string name = Set;
            name += '.';
            name += algos[i];
            name += "regex."s;
            name += suffix;
            names[i] = name;

            ofs[i].open(name);
            ofs[i] << "% n ms" << std::endl;
        }

        // mim::bench::do_bench(0, ofs, prog0);
        mim::bench::do_bench(1, ofs, prog1);
    } catch (const mim::Error& e) {
        std::cerr << e;
        return EXIT_FAILURE;
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        return EXIT_FAILURE;
    } catch (...) {
        std::cerr << "error: unknown exception" << std::endl;
        return EXIT_FAILURE;
    }
}
